Solve $|3x - 2| > |x + 6|$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, scale=0.55]
\draw[->] (-8,0) -- (6.5,0) node[right] {$x$};
\draw[->] (0,-1) -- (0,12.5) node[above] {$y$};
\node[below left] at (0,0) {$0$};
\draw[thick, blue, <->] (-3.167,11.5) -- (0.6667,0) -- (4.5,11.5) node[pos=0.9, right] {$y = |3x - 2|$};
\draw[thick, red, <->] (-7.5,1.5) -- (-6,0) -- (5.5,11.5) node[pos=0.85, left] {$y = |x + 6|$};
\fill (-6,0) circle (2.5pt) node[below] {$-6$};
\fill (0.6667,0) circle (2.5pt) node[below] {$\dfrac{2}{3}$};
\end{tikzpicture}
[/tikz]
